[
  {
    "title": "預檢請求",
    "body": "非簡單請求會先送 OPTIONS 預檢；伺服器須核准方法與自訂標頭，瀏覽器才送正式請求。",
    "examples": [
      "OPTIONS /users HTTP/1.1\nOrigin: https://app.example.com\nAccess-Control-Request-Method: DELETE\nAccess-Control-Request-Headers: X-Token"
    ]
  },
  {
    "title": "憑證與萬用字元",
    "body": "帶 Cookie 或其他憑證時，Allow-Origin 必須是具體來源，並搭配 Allow-Credentials: true；不能使用 *。",
    "examples": [
      "Access-Control-Allow-Origin: https://app.example.com\nAccess-Control-Allow-Credentials: true\nSet-Cookie: sid=abc; Secure"
    ]
  },
  {
    "title": "來源的組成",
    "body": "來源由協定、主機、埠組成；只要其中一項不同，即使路徑相同，也屬不同來源。",
    "examples": [
      "https://app.example.com:443 與 http://app.example.com:443 不同來源",
      "https://app.example.com 與 https://api.example.com 不同來源"
    ]
  }
]
